<?php
declare(strict_types=1);
if(PHP_SAPI!=='cli')exit(1);require_once dirname(__DIR__).'/src/Database.php';require_once dirname(__DIR__).'/src/CommerceDeliveryService.php';require_once dirname(__DIR__).'/src/CommerceShoppingDeliveryService.php';
try{$db=Database::connect(dirname(__DIR__));if(getenv('COMMERCE_MAIL_WORKER_ENABLED')!=='1')throw new RuntimeException('Disabled');$q=$db->prepare('SELECT id FROM commerce_organizations WHERE organization_key=?');$q->execute([CommerceAccess::primaryKey()]);$org=(int)$q->fetchColumn();if(!$org)throw new RuntimeException('Owner unavailable');$result=CommerceDeliveryService::process($db,$org,25);$q=$db->query("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='commerce_shopping_deliveries'");if((int)$q->fetchColumn()===1)$result['purchases']=CommerceShoppingDeliveryService::process($db,$org,25);echo json_encode($result).PHP_EOL;}catch(Throwable){fwrite(STDERR,"Commerce delivery worker disabled or unavailable. Inspect configured gates and normalized delivery errors; no recipient or message content is logged.\n");exit(1);}
